// Core poll, option, vote, and voter types. / 投票、选项、投票记录及投票者的核心类型。
export type PollStatus = "open" | "closed";

export interface PollOption {
  id: string;
  name: string;
  imageUrl?: string;
}

export interface VoterIdentity {
  id: string;
  nickname: string;
  avatar?: string;
}

export interface Vote {
  id: string;
  voter: VoterIdentity;
  selectedOptionId?: string;
  ranking: string[];
  submittedAt: string;
}

export interface PollComment {
  id: string;
  // Comments belong to the voter, not to a vote row: votes.id is generated by
  // Supabase on insert, so it cannot identify a comment across reloads.
  // 评论按投票者身份关联；votes.id 由数据库生成，刷新后无法用于匹配评论。
  voter: VoterIdentity;
  text: string;
  createdAt: string;
  optionId?: string;
}

export interface Poll {
  id: string;
  title: string;
  description: string;
  createdAt: string;
  creatorId?: string;
  commentsPublic?: boolean;
  endsAt?: string;
  status: PollStatus;
  options: PollOption[];
  votes: Vote[];
  comments: PollComment[];
}

export type VotingMode = "choice" | "ranking";
